-- Sprint 1b (D-040): the phone cover image fills the whole hero. The first one was black across its top half (the scene only in the lower half) and compressed hard enough to look blurry; this one is the scene edge to edge, encoded sharper.
-- Generated by scripts/build-hero-photos.mjs --replace; the encoded image(s) are in design/hero/. The slot's current
-- photo is superseded (BR-1.17: kept, never altered or deleted) and the new one becomes current — the owner can replace
-- it in Admin → Photos at any time. Additive only.


UPDATE "ProfilePhoto" SET "supersededAt" = now() WHERE "purpose" = 'hero-mobile' AND "supersededAt" IS NULL AND "sha256" <> '00dc4e7941228fc44726707d31fbd12bff9a8677ac1b82e23769c052a4f9704b';

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-mobile', 'A dark data-centre aisle, server racks rising on both sides, lit by thin orange fibre-optic lines that run to a distant vanishing point', 'image/webp', 1024, 1536, 119900, '00dc4e7941228fc44726707d31fbd12bff9a8677ac1b82e23769c052a4f9704b', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-mobile' AND "supersededAt" IS NULL);
